class WorkspaceOptions {
 public List<MaintenanceItem> Maintenance=new List<MaintenanceItem>();public bool PressureEnabled=false;public int CpuLimit=90,RamLimit=85,PressureSeconds=15,PressureCooldown=300;public bool StartupEnabled=true;public string StartupStyle="Orbit";public int StartupDuration=2800;public bool[] HomeSections={true,true,true,true,true,true,true};public string CustomBase="#171925",CustomAccent="#BCA4FF";public bool DailyPicture=false;public int PictureChoice=0,PictureShift=0;public string ThemeId="midnight";public string DisplayName="";public bool RiyadhTime=true,ShowHijri=true,Clock24=true;public int HijriOffset=0;public string PlayTheme="Nebula";public bool Motion=true;public int Interval=1000;public string Accent="Ocean";public bool AlwaysOnTop=false;public List<string> Pins=new List<string>{"Summary","Windows advisor","Processes"};
 public static string FileName=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Pulse","Workspace.json");
 public static WorkspaceOptions Read(){try{if(new FileInfo(FileName).Length>16384)return new WorkspaceOptions();var v=new JavaScriptSerializer().Deserialize<WorkspaceOptions>(File.ReadAllText(FileName));if(v==null)return new WorkspaceOptions();if(!new[]{1000,2000,3000,5000}.Contains(v.Interval))v.Interval=1000;if(v.Pins==null)v.Pins=new List<string>();v.Pins=v.Pins.Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct().Take(100).ToList();if(v.Maintenance==null)v.Maintenance=new List<MaintenanceItem>();v.Maintenance=v.Maintenance.Where(x=>x!=null&&!string.IsNullOrWhiteSpace(x.Title)&&x.Title.Length<=80&&x.RepeatDays>=0&&x.RepeatDays<=365).Take(24).ToList();return v;}catch{return new WorkspaceOptions();}}
 public void Save(){Directory.CreateDirectory(Path.GetDirectoryName(FileName));string temp=FileName+".tmp";File.WriteAllText(temp,new JavaScriptSerializer().Serialize(this));if(File.Exists(FileName))File.Replace(temp,FileName,null);else File.Move(temp,FileName);}
}
class MetricTile:Control {
 public string Caption,Value="—",Detail="Waiting for sample";public Color Accent;public double Level;
 public MetricTile(){DoubleBuffered=true;Margin=new Padding(0,0,12,12);Dock=DockStyle.Fill;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;if(Width<2||Height<2)return;using(var shape=PlayColors.Round(new RectangleF(0,0,Width-1,Height-1),14)){using(var b=new LinearGradientBrush(ClientRectangle,ThemePalette.Current.Raised,ThemePalette.Current.Surface,70f))g.FillPath(b,shape);using(var p=new Pen(ThemePalette.Current.Border))g.DrawPath(p,shape);}using(var f=new Font("Segoe UI",9,FontStyle.Bold))TextRenderer.DrawText(g,Caption,f,new Rectangle(18,16,Width-32,20),ThemePalette.Current.Muted,TextFormatFlags.EndEllipsis);using(var f=new Font("Segoe UI",26,FontStyle.Bold))TextRenderer.DrawText(g,Value,f,new Rectangle(15,39,Width-28,49),Color.White,TextFormatFlags.EndEllipsis);using(var f=new Font("Segoe UI",9))TextRenderer.DrawText(g,Detail,f,new Rectangle(18,94,Width-32,23),ThemePalette.Current.Muted,TextFormatFlags.EndEllipsis);using(var b=new SolidBrush(Accent))g.FillRectangle(b,0,Height-4,(float)(Width*Math.Max(0,Math.Min(1,Level))),4);}
}
class InsightTracker {
 public List<string> Events=new List<string>();int cpuRuns,ramRuns;DateTime lastCpu=DateTime.MinValue,lastRam=DateTime.MinValue;
 public void Add(Snapshot s){cpuRuns=s.Cpu>=90?cpuRuns+1:0;ramRuns=s.MemoryPercent>=85?ramRuns+1:0;if(cpuRuns>=5&&(s.Time-lastCpu).TotalMinutes>=5){Events.Insert(0,s.Time.ToString("T")+" · CPU ≥90% for 5 consecutive samples. Inspect busy processes; this can be expected during heavy work.");lastCpu=s.Time;cpuRuns=0;}if(ramRuns>=5&&(s.Time-lastRam).TotalMinutes>=5){Events.Insert(0,s.Time.ToString("T")+" · Memory ≥85% for 5 consecutive samples. Review unneeded apps after saving work.");lastRam=s.Time;ramRuns=0;}if(Events.Count>100)Events.RemoveRange(100,Events.Count-100);}
}
