trols.Add(bottom,0,3);navFilter.TextChanged+=(s,e)=>RebuildNavigation();var actions=new FlowLayoutPanel{Dock=DockStyle.Right,Width=295,FlowDirection=FlowDirection.RightToLeft};head.Controls.Add(actions);pinButton=Button("☆ Pin page");pinButton.Click+=(s,e)=>{if(preferences.Pins.Contains(page))preferences.Pins.Remove(page);else preferences.Pins.Add(page);SavePreferences();RebuildNavigation();StyleView();};actions.Controls.Add(pinButton);var jump=Button("⌕  Jump to…");jump.Click+=(s,e)=>ShowPalette();actions.Controls.Add(jump);RebuildNavigation();}
