 void UpdateTiles(){if(tileCpu==null||tileCpu.IsDisposed||current==null)return;tileCpu.Value=current.Cpu.ToString("F1")+"%";tileCpu.Detail=Environment.ProcessorCount+" logical processors";tileCpu.Level=current.Cpu/100;tileRam.Value=current.MemoryPercent.ToString("F1")+"%";tileRam.Detail=Inventory.Bytes(current.Available)+" available";tileRam.Level=current.MemoryPercent/100;tileGpu.Value=double.IsNaN(gpuValue)?"—":gpuValue.ToString("F1")+"%";tileGpu.Detail=double.IsNaN(gpuValue)?"Provider unavailable":"Windows GPU engine reading";tileGpu.Level=double.IsNaN(gpuValue)?0:gpuValue/100;tileNet.Value=Inventory.Bytes(current.Receive)+"/s";tileNet.Detail="↑ "+Inventory.Bytes(current.Send)+"/s sent";tileNet.Level=1;foreach(var t in new[]{tileCpu,tileRam,tileGpu,tileNet})t.Invalidate();}
 void TrackInsights(Snapshot s){insightTracker.Add(s);TrackPressure(s);TrackSessionTools(s);}
 string InsightsReport(){if(current==null)return "Waiting for measurements…";string output="SESSION INSIGHTS · "+current.Time.ToString("g")+"\r\n\r\nCPU "+current.Cpu.ToString("F1")+"%  ·  Memory "+current.MemoryPercent.ToString("F1")+"%  ·  "+current.Processes.Count+" processes\r\n";if(baseline!=null)output+="\r\nCompared with baseline at "+baseline.Time.ToString("T")+":\r\nCPU "+(current.Cpu-baseline.Cpu).ToString("+0.0;-0.0;0.0")+" percentage points\r\nMemory "+(current.MemoryPercent-baseline.MemoryPercent).ToString("+0.0;-0.0;0.0")+" percentage points\r\nProcesses "+(current.Processes.Count-baseline.Processes.Count).ToString("+0;-0;0")+"\r\n";else output+="\r\nCapture a baseline before making one change, then compare readings here.\r\n";output+="\r\nShort samples fluctuate. A difference does not prove a change caused it.\r\nLocal rules flag sustained CPU/memory pressure; this is not model-generated advice.\r\n";return output;}
 void BuildInsights(){sub.Text="Before / after readings · quiet session alerts · no extra sampler";var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,50));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,270));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,36));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(layout);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};var capture=Button("Capture baseline");capture.Click+=(s,e)=>{if(current!=null)baseline=current;RefreshInsights();};actions.Controls.Add(capture);var copy=Button("Copy evidence for AI / support");copy.Click+=(s,e)=>{try{Clipboard.SetText(InsightsReport()+"\r\n"+string.Join("\r\n",insightTracker.Events));}catch(Exception ex){MessageBox.Show(this,ex.Message);}};actions.Controls.Add(copy);var ask=Button("Prepare AI comparison");ask.Click+=(s,e)=>{string evidence=InsightsReport();Navigate("Windows advisor");var advisor=content.Controls.OfType<AdvisorPanel>().FirstOrDefault();if(advisor!=null)advisor.PrepareEvidence(evidence);};actions.Controls.Add(ask);var clear=Button("Clear session alerts");clear.Click+=(s,e)=>{insightTracker.Events.Clear();RefreshInsights();};actions.Controls.Add(clear);layout.Controls.Add(actions,0,0);insightText=Block("Waiting for readings…",11);layout.Controls.Add(insightText,0,1);layout.Controls.Add(new Label{Text="ACTIVITY · 5 consecutive high samples · 5-minute cooldown per metric · this session only",Dock=DockStyle.Fill,ForeColor=muted},0,2);insightEvents=new ListBox{Dock=DockStyle.Fill,BackColor=panel,ForeColor=Color.White,HorizontalScrollbar=true,BorderStyle=BorderStyle.None};layout.Controls.Add(insightEvents,0,3);lastInsightText="";RefreshInsights();}
 void RefreshInsights(){if(insightText==null||insightText.IsDisposed)return;insightText.Text=InsightsReport();string events=string.Join("\n",insightTracker.Events);if(events!=lastInsightText||insightEvents.Items.Count==0){lastInsightText=events;insightEvents.Items.Clear();insightEvents.Items.AddRange(insightTracker.Events.Count==0?new[]{"No sustained CPU or memory pressure alerts recorded in this session."}:insightTracker.Events.ToArray());}}
 void BuildPreferences(){sub.Text="Make this workspace yours · preferences saved locally";var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(20)};content.Controls.Add(flow);AddStartupPreferences(flow);AddPicturePreferences(flow);AddGreetingPreferences(flow);flow.Controls.Add(new Label{Text="A calmer workspace",AutoSize=true,Font=new Font("Segoe UI",24,FontStyle.Bold)});flow.Controls.Add(new Label{Text="Choose an accent, adjust monitoring, and pin the pages you use most.",AutoSize=true,ForeColor=muted,Margin=new Padding(0,12,0,25)});var gallery=Button("Open theme gallery →");gallery.Click+=(s,e)=>Navigate("Themes");flow.Controls.Add(gallery);flow.Controls.Add(new Label{Text="Sampling interval (longer intervals reduce monitoring work)",AutoSize=true,Margin=new Padding(0,20,0,8)});var interval=new ComboBox{Width=280,DropDownStyle=ComboBoxStyle.DropDownList};interval.Items.AddRange(new object[]{1000,2000,3000,5000});interval.SelectedItem=preferences.Interval;interval.SelectedIndexChanged+=(s,e)=>{preferences.Interval=(int)interval.SelectedItem;timer.Interval=preferences.Interval;SavePreferences();};flow.Controls.Add(interval);flow.Controls.Add(new Label{Text="Values are milliseconds: 1000 = one second. History graphs show 60 samples.",AutoSize=true,ForeColor=muted});var top=new CheckBox{Text="Keep Aster above other windows",AutoSize=true,Checked=preferences.AlwaysOnTop,Margin=new Padding(0,22,0,15)};top.CheckedChanged+=(s,e)=>{TopMost=preferences.AlwaysOnTop=top.Checked;SavePreferences();};flow.Controls.Add(top);flow.Controls.Add(new Label{Text="Use ☆ Pin page in the header to add or remove sidebar favorites.\r\nSearch the sidebar to filter pages. Ctrl+K jumps to any page.\r\nF5 refreshes the current view. Saved cases and AI tools are in Windows advisor.",AutoSize=true,ForeColor=muted,Margin=new Padding(0,20,0,0)});}
